using System;
using System.Collections.Generic;
using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class Dice : ScriptableObject
{
	[Header("Dice Data")]
	public string DiceName;

	public bool enableCustomDiceNameID;

	[ShowIf("enableCustomDiceNameID")]
	public string customDiceNameID;

	public bool RemoveAfterBattle;

	public DiceTier DiceTier;

	public DiceFace[] DiceFaces = new DiceFace[0];

	[NonSerialized]
	public DiceFace[] DiceFacesModded = new DiceFace[0];

	public DiceFace[] DiceFacesModdedMirror = new DiceFace[0];

	[HideInInspector]
	[ShowNonSerializedField]
	public bool MissingSomething;

	public bool MuteDiceForDemo = true;

	public bool Mod;

	public bool IsModdedDie()
	{
		if (!ReferenceSingleton<AssetsReference>.Instance.GameController.IsDailyRun && DiceFacesModded.Length != 0)
		{
			return true;
		}
		return false;
	}

	public DiceFace[] GetDiceFaces(bool ignoreMod = false)
	{
		if (!ignoreMod && IsModdedDie())
		{
			return DiceFacesModded;
		}
		return DiceFaces;
	}

	public void SetDiceFaces(DiceFace[] diceFaces)
	{
		if (IsModdedDie())
		{
			DiceFacesModded = diceFaces;
		}
		else
		{
			DiceFaces = diceFaces;
		}
	}

	public bool IsAnyDiceFaceNull()
	{
		for (int i = 0; i < GetDiceFaces().Length; i++)
		{
			if (GetDiceFaces()[i].BattleAction == null)
			{
				return true;
			}
			if (GetDiceFaces()[i].EnableSecondAction && GetDiceFaces()[i].SecondBattleAction == null)
			{
				return true;
			}
		}
		return false;
	}

	public void ToggleActionValueModifier(List<ActionValueModifier> actionValueModifiers)
	{
		for (int i = 0; i < GetDiceFaces().Length; i++)
		{
			GetDiceFaces()[i].ToggleActionValueModifier(actionValueModifiers);
		}
	}

	public void ResetActionValueModifiers()
	{
		for (int i = 0; i < GetDiceFaces().Length; i++)
		{
			GetDiceFaces()[i].ResetActionValueModifiers();
		}
	}

	public List<DiceFaceSave> GetForgedFaces()
	{
		List<DiceFaceSave> list = new List<DiceFaceSave>();
		for (int i = 0; i < GetDiceFaces().Length; i++)
		{
			DiceFace diceFace = GetDiceFaces()[i];
			if (diceFace.KeepChanges)
			{
				DiceFaceSave diceFaceSave = new DiceFaceSave();
				diceFaceSave.FaceIndex = i;
				diceFaceSave.FaceName = diceFace.FaceName;
				diceFaceSave.ActionValue = diceFace.ActionValue;
				if (diceFace.BattleAction != null)
				{
					diceFaceSave.BattleActionName = diceFace.BattleAction.name;
				}
				else
				{
					Debug.Log("---- diceFace.BattleAction is NULL ----");
				}
				if (diceFace.EnableSecondAction)
				{
					diceFaceSave.EnableSecondAction = diceFace.EnableSecondAction;
					diceFaceSave.SecondActionValue = diceFace.SecondActionValue;
					diceFaceSave.SecondBattleActionName = diceFace.SecondBattleAction.name;
				}
				list.Add(diceFaceSave);
			}
		}
		return list;
	}

	public int GetDiceFaceIndex(DiceFace diceFace)
	{
		for (int i = 0; i < GetDiceFaces().Length; i++)
		{
			if (diceFace == GetDiceFaces()[i])
			{
				return i;
			}
		}
		return -1;
	}

	public DiceFace[] CopyDiceFacesAsNewInstances()
	{
		DiceFace[] array = new DiceFace[GetDiceFaces().Length];
		for (int i = 0; i < array.Length; i++)
		{
			DiceFace diceFace = GetDiceFaces()[i];
			if (diceFace.EnableSecondAction)
			{
				array[i] = new DiceFace(diceFace.FaceName, diceFace.ActionValue, diceFace.BattleAction, diceFace.SecondActionValue, diceFace.SecondBattleAction);
			}
			else
			{
				array[i] = new DiceFace(diceFace.FaceName, diceFace.ActionValue, diceFace.BattleAction);
			}
			array[i].KeepChanges = diceFace.KeepChanges;
		}
		return array;
	}

	public DiceFace CopyDiceFaceAsNewInstances(int index)
	{
		DiceFace diceFace = GetDiceFaces()[index];
		if (diceFace.EnableSecondAction)
		{
			return new DiceFace(diceFace.FaceName, diceFace.ActionValue, diceFace.BattleAction, diceFace.SecondActionValue, diceFace.SecondBattleAction);
		}
		return new DiceFace(diceFace.FaceName, diceFace.ActionValue, diceFace.BattleAction);
	}

	public virtual string GetNameID()
	{
		if (enableCustomDiceNameID)
		{
			return customDiceNameID + "_N";
		}
		return DiceName.Replace("+", "").Replace(" ", "").Replace("Die", "") + "_N";
	}

	public string GetModdedName()
	{
		return DiceName.Replace("+", "");
	}

	public bool DiceHasAction(BattleAction battleAction)
	{
		for (int i = 0; i < GetDiceFaces().Length; i++)
		{
			if (GetDiceFaces()[i].BattleAction == battleAction)
			{
				return true;
			}
		}
		return false;
	}

	public bool DiceHasKeepChangesFlag()
	{
		for (int i = 0; i < GetDiceFaces().Length; i++)
		{
			if (GetDiceFaces()[i].KeepChanges)
			{
				return true;
			}
		}
		return false;
	}

	public Dice InstantiateScriptableObjectTryingToCopyDiceFacesModded()
	{
		Dice dice;
		if (this is PlayerDice)
		{
			dice = UnityEngine.Object.Instantiate(this) as PlayerDice;
			(dice as PlayerDice).Magnetized = (this as PlayerDice).Magnetized;
		}
		else
		{
			dice = UnityEngine.Object.Instantiate(this);
		}
		if (IsModdedDie())
		{
			dice.DiceFacesModded = new DiceFace[DiceFacesModded.Length];
			for (int i = 0; i < dice.DiceFacesModded.Length; i++)
			{
				dice.DiceFacesModded[i] = new DiceFace(DiceFacesModded[i]);
			}
		}
		return dice;
	}
}
